import math
import numpy as np


def steps_needed(kappa, eps, best=True):
    rho = (kappa - 1) / (kappa + 1) if best else 1 - 1 / kappa
    if rho <= 0:
        return 1
    return math.ceil(math.log(1 / eps) / math.log(1 / rho))


def observed_rate(errors):
    k = np.arange(len(errors))
    slope = np.polyfit(k, np.log(errors), 1)[0]
    return float(np.exp(slope))
